#include <stdint.h>
#include <stdio.h>

enum SizeStatus { INVALID_SIZE, BYTES_OK, SIZE_OVERFLOW };

static enum SizeStatus bytes_for(size_t count, size_t width, size_t *bytes)
{
    if (count == 0 || width == 0) {
        return INVALID_SIZE;
    }
    if (count > SIZE_MAX / width) {
        return SIZE_OVERFLOW;
    }
    *bytes = count * width;
    return BYTES_OK;
}

static void print_size(size_t count, size_t width)
{
    size_t bytes = 0;
    switch (bytes_for(count, width, &bytes)) {
    case BYTES_OK: printf("%zu\n", bytes); break;
    case SIZE_OVERFLOW: puts("overflow"); break;
    case INVALID_SIZE: puts("invalid"); break;
    }
}

int main(void)
{
    print_size(4, 3);
    print_size(SIZE_MAX, 2);
    print_size(3, 0);
    return 0;
}

