#include <stdint.h>
#include <ctype.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>

static int read_values(int values[], const int minimum[], const int maximum[], size_t count)
{
    char line[64];
    size_t length = 0;
    int ch;
    while ((ch = getchar()) != EOF && ch != '\n') {
        if (ch == 0 || length == sizeof line - 1) {
            return 0;
        }
        line[length++] = (char)ch;
    }
    if (ferror(stdin)) {
        return 0;
    }
    line[length] = '\0';

    char *cursor = line;
    for (size_t i = 0; i < count; ++i) {
        char *end;
        errno = 0;
        long value = strtol(cursor, &end, 10);
        if (end == cursor || errno == ERANGE || value < minimum[i] || value > maximum[i]) {
            return 0;
        }
        if (i + 1 < count && !isspace((unsigned char)*end)) {
            return 0;
        }
        values[i] = (int)value;
        cursor = end;
    }
    while (isspace((unsigned char)*cursor)) {
        ++cursor;
    }
    return *cursor == '\0';
}

enum SizeStatus { INVALID_SIZE, BYTES_OK, SIZE_OVERFLOW };

static enum SizeStatus bytes_for(size_t count, size_t width, size_t *bytes)
{
    if (count == 0 || width == 0) {
        return INVALID_SIZE;
    }
    if (count > SIZE_MAX / width) {
        /* TODO: return the distinct status for an overflowing size. */
        return INVALID_SIZE;
    }
    /* TODO: store the checked product. */
    *bytes = count;
    return BYTES_OK;
}

int main(void)
{
    int input[2];
    const int minimum[] = {-1, 0};
    const int maximum[] = {16, 8};
    if (!read_values(input, minimum, maximum, 2) || (input[0] == -1 && input[1] != 2)) {
        puts("invalid");
        return 0;
    }
    size_t count = input[0] == -1 ? SIZE_MAX : (size_t)input[0];
    size_t bytes = 0;
    enum SizeStatus status = bytes_for(count, (size_t)input[1], &bytes);
    if (status == BYTES_OK) {
        printf("bytes %zu\n", bytes);
    } else if (status == SIZE_OVERFLOW) {
        puts("overflow");
    } else {
        puts("invalid");
    }
    return 0;
}

